<script setup lang="ts">const{cancelDeletion,consents,deletionRequest,loadConsents,recordConsent,requestData}=useAccount(),notice=ref("");useHead({title:"حریم خصوصی — هفت‌سو",meta:[{name:"robots",content:"noindex,nofollow"}]});onMounted(()=>void loadConsents());function current(purpose:string){return consents.value.find(item=>item.purpose===purpose)?.granted??false}async function toggle(purpose:string,event:Event){await recordConsent(purpose,(event.target as HTMLInputElement).checked)}async function data(kind:"export"|"delete"){const request=await requestData(kind);notice.value=kind==="export"?"درخواست خروجی ثبت شد.":`حذف حساب برای ${new Date(request.execute_after).toLocaleDateString('fa-IR')} زمان‌بندی شد.`;}async function cancel(){await cancelDeletion();notice.value="درخواست حذف حساب لغو شد."}</script>
<template><AccountShell title="حریم خصوصی و داده‌های من" description="رضایت‌ها را کنترل کنید و نسخه‌ای از داده‌های حساب دریافت کنید."><section class="account-section"><h2>رضایت‌ها</h2><label class="toggle-row"><input type="checkbox" :checked="current('analytics')" @change="toggle('analytics',$event)">تحلیل ناشناس برای بهبود محصول</label><label class="toggle-row"><input type="checkbox" :checked="current('personalization')" @change="toggle('personalization',$event)">شخصی‌سازی پیشنهادها</label><label class="toggle-row"><input type="checkbox" :checked="current('marketing')" @change="toggle('marketing',$event)">پیام‌های بازاریابی</label></section><section class="account-section"><h2>داده‌های حساب</h2><p>خروجی حساب در صف امن آماده‌سازی قرار می‌گیرد. حذف حساب ۳۰ روز مهلت بازگشت دارد.</p><div class="privacy-actions"><button class="button button-secondary" type="button" @click="data('export')">درخواست خروجی داده‌ها</button><button v-if="!deletionRequest" class="button button-danger" type="button" @click="data('delete')">درخواست حذف حساب</button><button v-else class="button button-secondary" type="button" @click="cancel">لغو حذف زمان‌بندی‌شده</button></div><p v-if="notice" class="inline-success" role="status">{{notice}}</p></section></AccountShell></template>
